code='''def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # A horizontal 5-bar repeats the vertical color strip attached below its end.
    for r in range(h):
        c = 0
        while c < w:
            if g[r][c] != 5:
                c += 1
                continue
            a = c
            while c < w and g[r][c] == 5:
                c += 1
            b = c
            if b - a < 2 or r + 1 >= h:
                continue
            seed = []
            rr = r + 1
            while rr < h and g[rr][a] not in (0, 5):
                seed.append(g[rr][a])
                rr += 1
            if seed:
                for cc in range(a, b):
                    for i, color in enumerate(seed):
                        if r + 1 + i < h:
                            g[r + 1 + i][cc] = color

    # A vertical 5-bar repeats the attached rectangular color patch along its length.
    for c in range(w):
        r = 0
        while r < h:
            if g[r][c] != 5:
                r += 1
                continue
            top = r
            while r < h and g[r][c] == 5:
                r += 1
            bottom = r - 1
            if bottom - top < 1 or c + 1 >= w:
                continue
            # Find the patch touching the bar at its lower endpoint.
            seed_top = bottom
            while seed_top >= top and g[seed_top][c + 1] not in (0, 5):
                seed_top -= 1
            seed_top += 1
            if seed_top > bottom or g[bottom][c + 1] in (0, 5):
                continue
            seed_bottom = bottom
            while seed_bottom + 1 < h and g[seed_bottom + 1][c + 1] not in (0, 5):
                seed_bottom += 1
            seed = []
            for rr in range(seed_top, seed_bottom + 1):
                row = []
                cc = c + 1
                while cc < w and g[rr][cc] not in (0, 5):
                    row.append(g[rr][cc])
                    cc += 1
                seed.append(row)
            if not seed or any(len(row) != len(seed[0]) for row in seed):
                continue
            for rr in range(top, bottom + 1):
                pattern_row = seed[(rr - seed_top) % len(seed)]
                for j, color in enumerate(pattern_row):
                    if c + 1 + j < w:
                        g[rr][c + 1 + j] = color
    return g
